csui.define('d2/widgets/checkedouttable/checkedouttable.view',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/lib/backbone',
  'nuc/lib/marionette',
  'd2/utils/contexts/factories/checkout.factory',
  'd2/widgets/checkedouttable/checkedout.widgettable.view',
  'd2/widgets/widget.container/perspective.table.container.view'
], function($, _, Backbone, Marionette, D2CheckoutFactory, D2CheckedoutTable, PerspectiveTableContainer) {
  'use strict';

  var CheckedoutTableView = PerspectiveTableContainer.extend({

      constructor: function CheckedoutTableView(/* options */ ){
        PerspectiveTableContainer.prototype.constructor.apply(this, arguments);
      },

      getWidgetViewClass: function(){
        return D2CheckedoutTable;
      },

      resolveDataForTable: function(){
        return this.checkDataFetchedWithContext(D2CheckoutFactory);
      }
  })

  return CheckedoutTableView;
})
;