csui.define('d2/widgets/splitview.widgets/impl/splitview.doclist.toolbaritems.mask',[
    'module',
    'nuc/lib/underscore',
    'csui/controls/toolbar/toolitems.mask',
    'csui/utils/toolitem.masks/global.toolitems.mask',
    'csui/widgets/nodestable/toolbaritems',
], function (module, _, ToolItemMask, GlobalMenuItemsMask, d2collectionsToolItems) {
    'use strict';

    function SplitViewDocListToolbarItemsMasks() {
        this.initializeMasks();
    }

    SplitViewDocListToolbarItemsMasks.prototype.initializeMasks = function() {
        var toolbars = _.keys(d2collectionsToolItems),
            config = module.config();

        this.toolbars = _.reduce(toolbars, function (toolbars, toolbar) {
            var mask = new ToolItemMask(new GlobalMenuItemsMask(), {normalize: false});
            // Masks passed in by separate require.config calls are sub-objects
            // stored in the outer object be different keys
            _.each(config, function (source, key) {
                if (source && key === toolbar) {
                    mask.extendMask(source);
                }
            });
            // Enable restoring the mask to its initial state
            mask.storeMask();
            toolbars[toolbar] = mask;
            return toolbars;
        }, {});
        SplitViewDocListToolbarItemsMasks.toolbars = toolbars;
    };

    return SplitViewDocListToolbarItemsMasks;

});
