csui.define('d2/widgets/admin/checkout/checkout.view',[
  'd2/utils/contexts/factories/admin.checkout.factory',
  'd2/widgets/widgettile/widgettile.view',
  'i18n!d2/widgets/checkout/impl/nls/lang'
], function (AdminCheckoutCollectionFactory, WidgetTileView, lang) {
  'use strict';

  var AdminCheckoutView = WidgetTileView.extend({

    constructor: function AdminCheckoutView(options) {
      options = options || {};
      options.lang = lang;
      options.collectionFactory = AdminCheckoutCollectionFactory;
      WidgetTileView.prototype.constructor.apply(this, arguments);
    },

    getFactoryParam: function () {
      // Fix for DTWO-114653,
      // Setting the same value of AdminCheckoutCollectionFactory's propertyPrefix
      return "admincheckedout";
    }

  });

  return AdminCheckoutView;
});
