csui.define('d2/overrides/csui/controls/list/list.view',['nuc/utils/base',
  'csui/controls/list/list.view'], function (base, ListView) {

  let origRender = ListView.prototype.onRender;

  ListView.prototype.onRender = function () {
    origRender.apply(this, arguments);

    /*
    *In csui/controls/list/list.view.js:185, we have the following line which will add "cs-no-expanding" class and also adds
    * mouse events to show/hide list header icons for non apple based devices
    *   >>> base.isAppleMobile() === false && this._enableOpenPerspective && this._addActivationEventHandlers()
    * So in android tablet and in non apple hybrid devices (like MS Surface laptop), the icons in tile-header will be hidden
    * So removing cs-no-expanding class from el to show the tile header icons upfront in touch supported device,
    * and also we can listen for mouse based events if trigged.
    * */

    if (base.isHybrid() && this._enableOpenPerspective) {
      if(base.isAppleMobile()){
        this._addActivationEventHandlers();
      }
       this.$el.removeClass('cs-no-expanding');
    }
  };

});