csui.define('d2/dialogs/new.file/create/table.columns',["nuc/lib/backbone",
  'i18n!d2/dialogs/new.file/create/impl/nls/lang'
], function (Backbone, lang) {

  var TableColumnModel = Backbone.Model.extend({

    idAttribute: "key",

    defaults: {
      key: null,  // key from the resource definitions
      sequence: 0 // smaller number moves the column to the front
    }

  });

  var TableColumnCollection = Backbone.Collection.extend({

    model: TableColumnModel,
    comparator: "sequence",

    getColumnKeys: function () {
      return this.pluck('key');
    },

    deepClone: function () {
      return new TableColumnCollection(
          this.map(function (column) {
            return column.attributes;
          }));
    }

  });

  var tableColumns = new TableColumnCollection([
    {
      key: 'type',
      column_key: 'type',
      sequence: 2,
      definitions_order: 2,
      sort: false,
      repeating: false,
      title: lang.typeColumnHeader,
      type: -1,
      permanentColumn: true // don't wrap column due to responsiveness into details row
    },
    {
      key: 'template_object_name',
      column_key: 'template_object_name',
      sequence: 3,
      definitions_order: 3,
      sort: true,
      title: lang.nameColumnHeader,
      type: -1,
      widthFactor: 1.2,
      permanentColumn: true, // don't wrap column due to responsiveness into details row
      isNaming: true
    },
    {
      key: 'template_title',
      column_key: 'template_title',
      sequence: 4,
      sort: true,
      definitions_order: 4,
      title: lang.titleColumnHeader,
      type: -1,
      permanentColumn: true // don't wrap column due to responsiveness into details row
    },
    {
      key: 'template_subject',
      column_key: 'template_subject',
      sort: true,
      sequence: 5,
      definitions_order: 5,
      title: lang.subjectColumnHeader,
      type: -1,
      permanentColumn: true // don't wrap column due to responsiveness into details row
    }
  ]);

  return tableColumns;

});
