csui.define('d2/models/folder.structure.config',[
  'nuc/lib/underscore',
  'nuc/lib/backbone'
], function (_, Backbone) {
  'use strict';

  var FolderStructureConfigModel = Backbone.Model.extend({
    idAttribute: 'id',

    constructor: function FolderStructureConfigModel() {
      Backbone.Model.prototype.constructor.apply(this, arguments);
    },

    parse: function (response) {
      var content = response.content,
        links = _.isArray(response.links) ? response.links : [];

      links = links.concat(content.links);

      var properties = _.extend({}, _.omit(response, 'content'), content, {links: links});
      return properties;
    }
  });

  return FolderStructureConfigModel;
});