csui.define('d2/dialogs/new.file/create/vdoc.table.columns',["nuc/lib/backbone",
  'i18n!d2/dialogs/new.file/create/impl/nls/lang'
], function (Backbone, lang) {

  var VdocTableColumnModel = Backbone.Model.extend({

    idAttribute: "key",

    defaults: {
      key: null,  // key from the resource definitions
      sequence: 0 // smaller number moves the column to the front
    }

  });

  var VdocTableColumnCollection = Backbone.Collection.extend({

    model: VdocTableColumnModel,
    comparator: "sequence",

    getColumnKeys: function () {
      return this.pluck('key');
    },

    deepClone: function () {
      return new VdocTableColumnCollection(
          this.map(function (column) {
            return column.attributes;
          }));
    }
  });

  var vdocTableColumns = new VdocTableColumnCollection([
    {
      key: 'name',
      column_key: 'name',
      sequence: 1,
      definitions_order: 1,
      sort: true,
      title: lang.nameColumnHeader,
      type: -1,
      permanentColumn: true, // don't wrap column due to responsiveness into details row
      isNaming: true
    }
  ]);
  return vdocTableColumns;
});