csui.define('d2/commands/aviator/remove.assignments',[
  'nuc/lib/jquery',
  'csui/models/command',
  'csui/utils/commandhelper',
  'i18n!d2/commands/nls/localized.strings',
], function ($, CommandModel, CommandHelper, lang) {
  'use strict';

  const RemoveAssignments = CommandModel.extend({
    defaults: {
      signature: 'Aviator-RemoveAssignment',
      command_key: 'Aviator-RemoveAssignment',
      name: lang.CommandAviatorRemoveAssignment,
      scope: 'multiple'
    },

    execute: function (status/*, options*/) {
      const nodes = CommandHelper.getAtLeastOneNode(status),
        deferred = $.Deferred();
      status.collection.remove(nodes.models);
      // when all nodes are removed, nodespagination view has a logic to adjust the skipCount back to previous page.
      // But when we have only one page, skipCount becomes negative, and pagionation bar will have negative page numbers.
      // look for the logic under the comment "update skipCount when we delete all the items in last page" in smart/.../nodespagination.view
      status.collection.skipCount = Math.max(0, status.collection.skipCount);
      status.collection.fetch({ reload: false }).always(() => deferred.resolve());
      return deferred.promise();
    }
  });

  return RemoveAssignments;
});
