csui.define('d2/overrides/csui/controls/form/fields/base/csformarrayfield.editable.behavior',[
  'nuc/lib/underscore', 'nuc/lib/jquery',
  'csui/controls/form/fields/base/csformarrayfield.editable.behavior'
], function (_, $, FormArrayFieldEditableBehavior) {
  'use strict';
  var prototype = FormArrayFieldEditableBehavior.prototype;
  var oldEventsFn = prototype.events;
  var oldOnFocusOutWrite = prototype.onFocusOutWrite;


  prototype.events = function () {
    if (this.view.model.attributes.options.isGridField) {
      // in the csui implemtation , the mouse move events on fields are listened which is not required
      return _.extend({}, FormArrayFieldEditableBehavior.prototype.events, {
        'focusin @ui.flagWriteField': 'actionOnFocusIn',
        'focusin @ui.subInputField': 'actionOnFocusIn', // subInputFileds are like, images within
        // the input fields, for example, calendar icon in date input field, and flag-on and
        // flag-off images within flag input field, etc.,
        'focusout @ui.writeField': 'onFocusOutWrite',
        'focusin @ui.writeField': 'onFocusInWrite',
        'keyup': 'onKeyUp',
        'dp.change': 'onKeyUp'
      });
    } else {
      oldEventsFn.call(this);
    }

  };

  prototype.onFocusOutWrite = function (/*event*/) {
    // for a field inside a grid fire the validity event on focus out because
    // the bulk submit is done by array field only on focus out of the entire grid
    if ((this.view.model.attributes.options && this.view.model.attributes.options.isGridField)
      || (this.view.alpacaField.options && this.view.alpacaField.options.isGridField)
    ) {
      //Need to add timeout so that the active element is updated
      var args = arguments;
      setTimeout(function () {
        oldOnFocusOutWrite.apply(this, args);
        this.view.alpacaField && (this.view.alpacaField.focusout = true);
        if (this.view.alpacaField.isValid()) {
          this.$el.trigger($.Event('field:valid'), this.view);
        } else {
          this.$el.trigger($.Event('field:invalid'), this.view);
        }
      }.bind(this));
    } else {
      oldOnFocusOutWrite.apply(this, arguments);
    }
  };

});
