csui.define('d2/widgets/workflowstable/workflow.toolbaritems.masks',[
  'module',
  'nuc/lib/underscore',
  'csui/controls/toolbar/toolitems.mask',
  'csui/utils/toolitem.masks/global.toolitems.mask',
  'd2/widgets/workflowstable/workflow.toolbaritems'
], function (module, _, ToolItemMask, GlobalMenuItemsMask, workflowToolItems) {
  'use strict';

  function WorkflowToolbarItemsMasks() {
    this.initializeMasks();
  }

  WorkflowToolbarItemsMasks.prototype.initializeMasks = function() {
    var toolbars = _.keys(workflowToolItems),
      config = module.config();

    toolbars.push('timelineDigitalSignatureInlineActionBar');

    this.toolbars = _.reduce(toolbars, function (toolbars, toolbar) {
      var mask = new ToolItemMask(new GlobalMenuItemsMask(), {normalize: false});
      // Masks passed in by separate require.config calls are sub-objects
      // stored in the outer object be different keys
      _.each(config, function (source/*, key*/) {
        source = source[toolbar];
        if (source) {
          mask.extendMask(source);
        }
      });
      // Enable restoring the mask to its initial state
      mask.storeMask();
      toolbars[toolbar] = mask;
      return toolbars;
    }, {});
    WorkflowToolbarItemsMasks.toolbars = toolbars;
  };
  return WorkflowToolbarItemsMasks;
});