csui.define('d2/widgets/recentlyaccessedtable/recentlyaccessedtable.view',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/lib/backbone',
  'nuc/lib/marionette',
  'csui/utils/contexts/factories/recentlyaccessed',
  'd2/widgets/recentlyaccessedtable/recentlyaccessed.widgettable.view',
  'd2/widgets/widget.container/perspective.table.container.view'
], function($, _, Backbone, Marionette, D2RecentlyAccessedFactory, D2RecentlyAccessedTable, PerspectiveTableContainer) {
  'use strict';

  var RecentlyAccessedTableView = PerspectiveTableContainer.extend({

      constructor: function RecentlyAccessedTableView(/* options */ ){
        PerspectiveTableContainer.prototype.constructor.apply(this, arguments);
      },

      getWidgetViewClass: function(){
        return D2RecentlyAccessedTable;
      },

      resolveDataForTable: function(){
        return this.checkDataFetchedWithContext(D2RecentlyAccessedFactory);
      }
  })

  return RecentlyAccessedTableView;
})
;