csui.define('d2/widgets/shortcut/impl/url.shortcut.behavior',[
  'd2/widgets/shortcut/shortcut.behavior',
  'dctmw/utils/utils'
], function(ShortcutBehavior, utils){
  'use strict';

  var URLShortcutBehavior = ShortcutBehavior.extend({
    onClick: function() {
      if(this.options.data.url) {
        utils.openUrlInWindow(this.options.data.url, window.open(''));
      }
    }
  });

  return URLShortcutBehavior;
});